// The Invariant CRC of a real RoCEv2 RDMA WRITE frame.
//
// The frame below is vector `rc_write_only_16` from
// `tests/vectors/write_vectors.txt`, generated by Scapy: an RC
// RDMA_WRITE_ONLY carrying a 16-byte payload to queue pair 0x000111 at
// packet sequence number 1. Its correct ICRC is 0xb3d6ae42 on the wire.
//
// What to look for:
//
//   - `start` on the first cycle re-seeds the remainder. The seed is
//     0xDEBB20E3, not all-ones: that is the CRC-32 remainder after the
//     eight all-ones bytes the ICRC prepends, so the prefix costs no
//     cycles at all.
//   - `enable` is asserted from frame offset 14 -- the first byte of the
//     IPv4 header -- and stops before the 4-byte ICRC field. The
//     Ethernet header is not covered.
//   - `frame_index` is what selects the masking. Watch offsets 15, 22,
//     24, 25, 40, 41 and 46: the byte driven in is the real one, but the
//     CRC sees 0xFF, because a router is allowed to change those fields
//     in flight.
//   - `wire` lags `byte` by one cycle, because the remainder is
//     registered, and it is the byte-reversed form -- the on-wire ICRC
//     field is little-endian, unlike every other field in the packet.
//
// Deterministic (no RNG), so the committed trace regenerates
// byte-identically.

use rhdl::prelude::*;
use rhdl_fpga::doc::render_svg_markdown;
use rhdl_roce::icrc::{COVERAGE_START, Icrc, In};

const FRAME: &str = concat!(
    "ec0d9aaabbcc000a3501020308004500004c000000004011f714c0a80132c0a8010a",
    "123412b7003800000a00ffff000001110000000100007f00123400000000a5a50000",
    "0010000102030405060708090a0b0c0d0e0fb3d6ae42"
);

fn frame_bytes() -> Vec<u8> {
    (0..FRAME.len() / 2)
        .map(|i| u8::from_str_radix(&FRAME[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn main() -> Result<(), RHDLError> {
    let frame = frame_bytes();
    let covered_end = frame.len() - 4; // the ICRC field is not covered

    let mut stream: Vec<In> = vec![In {
        byte: bits(0),
        frame_index: bits(0),
        enable: false,
        start: true,
    }];
    for (idx, &byte) in frame.iter().enumerate() {
        let covered = idx >= COVERAGE_START as usize && idx < covered_end;
        stream.push(In {
            byte: bits(byte as u128),
            frame_index: bits(idx as u128),
            enable: covered,
            start: false,
        });
    }
    // One idle cycle so the last covered byte's result reaches the output.
    stream.push(In {
        byte: bits(0),
        frame_index: bits(0),
        enable: false,
        start: false,
    });

    let uut = Icrc::default();
    let input = stream.into_iter().with_reset(1).clock_pos_edge(100);
    let vcd = uut.run(input).collect::<SvgFile>();
    // Written relative to *this* crate's manifest dir;
    // `write_svg_as_markdown` would resolve against rhdl-fpga's.
    let markdown = render_svg_markdown(
        vcd,
        SvgOptions::default().with_io_filter().with_label_width(22),
    )
    .expect("rendering the waveform");
    let doc = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("doc");
    std::fs::create_dir_all(&doc).expect("creating doc/");
    std::fs::write(doc.join("icrc.md"), markdown).expect("writing doc/icrc.md");
    Ok(())
}
